/**
 * KS-480 §4 amendment — the Organisation-provisioning gate.
 *
 * Imports the REAL `requireOrgProvisioner` from routes/platform.ts rather than
 * restating it, so the assertions cannot drift from the shipped middleware (the
 * older platformRbac test mirrors its guard, which is the drift risk this
 * avoids).
 *
 * The gate answers "may this caller provision an Organisation at all"; the
 * per-call guardrails it enables (own-tenant pinning, no scope widening, no
 * rotation) live in the route handler and are covered by the live probes on the
 * ticket. The escalation limits on the mint itself live in the security
 * service's provisioningPolicy.
 */

import { describe, it, expect, vi } from 'vitest';
import type { Request, Response, NextFunction } from 'express';
import { requireOrgProvisioner } from '../routes/platform';

function harness(user: Record<string, unknown> | undefined) {
  const req = { user } as unknown as Request;
  let status = 0;
  let body: unknown = null;
  const res = {
    status(c: number) { status = c; return res as unknown as Response; },
    json(b: unknown) { body = b; return res as unknown as Response; },
  } as unknown as Response;
  const next = vi.fn() as unknown as NextFunction;
  requireOrgProvisioner(req, res, next);
  return {
    status,
    body: body as { error?: { message?: string } } | null,
    passed: (next as unknown as ReturnType<typeof vi.fn>).mock.calls.length === 1,
    kind: (req as { provisionerKind?: string }).provisionerKind,
  };
}

describe('requireOrgProvisioner — platform-admin path (pre-amendment behaviour)', () => {
  it.each(['super_admin', 'SUPER_ADMIN', 'platform_admin', 'SYSTEM_ADMIN'])('admits %s as admin', (role) => {
    const r = harness({ role });
    expect(r.passed).toBe(true);
    expect(r.kind).toBe('admin');
  });
});

describe('requireOrgProvisioner — provisioning-key path (the amendment)', () => {
  it('admits a connector carrying organizations:register, marked as connector', () => {
    const r = harness({ role: 'connector', scopes: ['organizations:register'], tenantId: 'ten-1' });
    expect(r.passed).toBe(true);
    expect(r.kind).toBe('connector');
  });

  it('admits it via a resource wildcard (hasScope semantics)', () => {
    const r = harness({ role: 'connector', scopes: ['organizations:*'], tenantId: 'ten-1' });
    expect(r.passed).toBe(true);
    expect(r.kind).toBe('connector');
  });
});

describe('requireOrgProvisioner — refusals', () => {
  it('refuses a connector WITHOUT the provisioning scope (the §8 document set is not enough)', () => {
    const r = harness({ role: 'connector', scopes: ['documents:write', 'anchors:write'], tenantId: 'ten-1' });
    expect(r.passed).toBe(false);
    expect(r.status).toBe(403);
    expect(r.body?.error?.message).toMatch(/organizations:register/);
  });

  it.each(['HOLDER', 'ISSUER', 'VERIFIER', 'ORG_ADMIN'])('refuses the non-platform role %s', (role) => {
    const r = harness({ role });
    expect(r.passed).toBe(false);
    expect(r.status).toBe(403);
  });

  it('401s an unauthenticated request rather than 403', () => {
    const r = harness(undefined);
    expect(r.passed).toBe(false);
    expect(r.status).toBe(401);
  });

  it('does not mark provisionerKind on a refusal', () => {
    expect(harness({ role: 'HOLDER' }).kind).toBeUndefined();
  });
});
